import { NextResponse } from 'next/server';
import { createActionProposal } from '@/lib/operational/common';
export const dynamic='force-dynamic';
type Cred={label?:string;scopes?:string[]};
function credential(req:Request){const token=req.headers.get('authorization')?.replace(/^Bearer\s+/i,'').trim();if(!token)return null;try{const map=JSON.parse(process.env.SFI_EXTERNAL_API_KEYS_JSON||'{}') as Record<string,Cred>;const c=map[token];return c&&(c.scopes?.includes('propose')||c.scopes?.includes('*'))?c:null}catch{return null}}
export async function POST(req:Request){const cred=credential(req);if(!cred)return NextResponse.json({ok:false,error:'unauthorized'},{status:401});const body=await req.json().catch(()=>({})) as Record<string,unknown>;const title=String(body.title||'').trim(),summary=String(body.summary||'').trim();if(!title||!summary)return NextResponse.json({ok:false,error:'title_and_summary_required'},{status:400});const actor=`external:${cred.label||'agent'}`;const result=await createActionProposal({proposalType:'external_agent_proposal',actorId:actor,title,objective:summary,status:'proposed',payload:{summary,requested_action:body.action??null,source:'external_agent_gateway',credential_label:cred.label||'external-agent',submitted_at:new Date().toISOString(),human_approval_required:true}});if(!result.ok)return NextResponse.json(result,{status:500});return NextResponse.json({ok:true,data:result.data,message:'Propuesta registrada. ROOT debe decidir antes de cualquier realización.'},{status:201});}
